1	/**
2	 * webauthn.ts  —  @askmi/shared-crypto
3	 *
4	 * Ersetzt die Software-ECDSA-Simulation durch echte
5	 * navigator.credentials (FIDO2/WebAuthn) API-Aufrufe.
6	 *
7	 * Architektur-Invarianten:
8	 *   - decisionId ist die WebAuthn-Challenge → bindet Biometrie an genau
9	 *     eine Policy-Entscheidung (nicht wiederverwendbar)
10	 *   - Kein Server-Roundtrip für die Challenge (lokal generiert)
11	 *   - userVerification: 'required' → erzwingt PIN/Biometrie auf Gerät
12	 *   - Fallback: wenn navigator.credentials nicht verfügbar (Node/Test),
13	 *     wird eine deterministisch signierte Software-Signatur genutzt
14	 *
15	 * Produktionshinweis:
16	 *   - rpId muss dem echten Hostname entsprechen (keine localhost-Probleme)
17	 *   - Passkey wird im Browser-Authenticator gespeichert (Plattform-Key)
18	 *   - Für native Apps: WebAuthn durch FIDO2 SDK ersetzen
19	 */
20	
21	import { canonicalStringify } from './hashing.js';
22	import { ASKMI_STORAGE_KEYS } from '@askmi/shared-types';
23	
24	// ── Typen ────────────────────────────────────────────────────────────────────
25	
26	export interface PasskeyRegistration {
27	  credentialId: string; // base64url-encoded credential ID
28	  publicKeyJwk: JsonWebKey | null; // Nur wenn exportierbar
29	  rpId: string;
30	  registeredAt: string;
31	}
32	
33	export interface PresenceProof {
34	  signature: string; // base64-encoded assertion signature
35	  credentialId: string; // Welcher Passkey wurde verwendet
36	  challenge: string; // Echo des decisionId (Anti-Replay)
37	  authenticatorData: string; // base64 authenticatorData vom Gerät
38	  verifiedAt: string;
39	  method: 'webauthn' | 'software-fallback';
40	}
41	
42	// ── Passkey-Storage (IndexedDB — persistiert, kein PII, nur Metadaten) ──────────────
43	
44	const PASSKEY_DB_NAME = ASKMI_STORAGE_KEYS.passkeyDb;
45	const PASSKEY_STORE_NAME = 'passkeys';
46	const PASSKEY_STORAGE_KEY = ASKMI_STORAGE_KEYS.passkeyRegistration;
47	const IDENTITY_KEY_STORAGE_KEY = ASKMI_STORAGE_KEYS.identityKeyRegistration;
48	
49	function getPasskeyDB(): Promise<IDBDatabase> {
50	  return new Promise((resolve, reject) => {
51	    if (typeof indexedDB === 'undefined') {
52	      reject(new Error('IndexedDB not available'));
53	      return;
54	    }
55	    const request = indexedDB.open(PASSKEY_DB_NAME, 1);
56	    request.onupgradeneeded = (event) => {
57	      const db = (event.target as IDBOpenDBRequest).result;
58	      if (!db.objectStoreNames.contains(PASSKEY_STORE_NAME)) {
59	        db.createObjectStore(PASSKEY_STORE_NAME);
60	      }
61	    };
62	    request.onsuccess = (event) => resolve((event.target as IDBOpenDBRequest).result);
63	    request.onerror = (event) => reject((event.target as IDBOpenDBRequest).error);
64	  });
65	}
66	
67	async function savePasskeyMeta(meta: PasskeyRegistration): Promise<void> {
68	  try {
69	    const db = await getPasskeyDB();
70	    return new Promise((resolve, reject) => {
71	      const tx = db.transaction(PASSKEY_STORE_NAME, 'readwrite');
72	      const store = tx.objectStore(PASSKEY_STORE_NAME);
73	      const request = store.put(JSON.stringify(meta), PASSKEY_STORAGE_KEY);
74	      request.onsuccess = () => resolve();
75	      request.onerror = () => reject(request.error);
76	    });
77	  } catch (err) {
78	    throw new Error(
79	      `Failed to persist passkey metadata: ${(err as Error)?.message ?? String(err)}`
80	    );
81	  }
82	}
83	
84	async function loadPasskeyMeta(): Promise<PasskeyRegistration | null> {
85	  try {
86	    const db = await getPasskeyDB();
87	    return new Promise((resolve, reject) => {
88	      const tx = db.transaction(PASSKEY_STORE_NAME, 'readonly');
89	      const store = tx.objectStore(PASSKEY_STORE_NAME);
90	      const request = store.get(PASSKEY_STORAGE_KEY);
91	      request.onsuccess = () => {
92	        const raw = request.result;
93	        resolve(raw ? JSON.parse(raw) : null);
94	      };
95	      request.onerror = () => reject(request.error);
96	    });
97	  } catch {
98	    return null;
99	  }
100	}
101	
102	async function saveIdentityKeyMeta(meta: PasskeyRegistration): Promise<void> {
103	  try {
104	    const db = await getPasskeyDB();
105	    return new Promise((resolve, reject) => {
106	      const tx = db.transaction(PASSKEY_STORE_NAME, 'readwrite');
107	      const store = tx.objectStore(PASSKEY_STORE_NAME);
108	      const request = store.put(JSON.stringify(meta), IDENTITY_KEY_STORAGE_KEY);
109	      request.onsuccess = () => resolve();
110	      request.onerror = () => reject(request.error);
111	    });
112	  } catch (err) {
113	    throw new Error(
114	      `Failed to persist identity-key metadata: ${(err as Error)?.message ?? String(err)}`
115	    );
116	  }
117	}
118	
119	async function loadIdentityKeyMeta(): Promise<PasskeyRegistration | null> {
120	  try {
121	    const db = await getPasskeyDB();
122	    return new Promise((resolve, reject) => {
123	      const tx = db.transaction(PASSKEY_STORE_NAME, 'readonly');
124	      const store = tx.objectStore(PASSKEY_STORE_NAME);
125	      const request = store.get(IDENTITY_KEY_STORAGE_KEY);
126	      request.onsuccess = () => {
127	        const raw = request.result;
128	        resolve(raw ? JSON.parse(raw) : null);
129	      };
130	      request.onerror = () => reject(request.error);
131	    });
132	  } catch {
133	    return null;
134	  }
135	}
136	
137	// ── Hilfsfunktionen ──────────────────────────────────────────────────────────
138	
139	function base64urlToBuffer(base64url: string): ArrayBuffer {
140	  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
141	  const binary = atob(base64);
142	  return new Uint8Array([...binary].map((c) => c.charCodeAt(0))).buffer;
143	}
144	
145	function bufferToBase64(buffer: ArrayBuffer): string {
146	  return btoa(String.fromCharCode(...new Uint8Array(buffer)));
147	}
148	
149	function bufferToBase64url(buffer: ArrayBuffer): string {
150	  return bufferToBase64(buffer).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
151	}
152	
153	/** Prüft ob echter WebAuthn verfügbar ist */
154	function isWebAuthnAvailable(): boolean {
155	  return (
156	    typeof navigator !== 'undefined' &&
157	    typeof navigator.credentials !== 'undefined' &&
158	    typeof navigator.credentials.get === 'function' &&
159	    typeof PublicKeyCredential !== 'undefined'
160	  );
161	}
162	
163	// ── Software-Fallback (Test / Node / ältere Browser) ────────────────────────
164	
165	/**
166	 * Wird nur verwendet wenn navigator.credentials nicht verfügbar.
167	 * Erzeugt eine deterministisch signierte Attestation über WebCrypto.
168	 * KEIN echter Presence-Proof — nur für Demo/Test-Environments.
169	 */
170	class SoftwareFallback {
171	  private static keyPair: CryptoKeyPair | null = null;
172	
173	  static async getOrCreateKey(): Promise<CryptoKeyPair> {
174	    if (!this.keyPair) {
175	      this.keyPair = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, [
176	        'sign',
177	        'verify',
178	      ]);
179	    }
180	    return this.keyPair;
181	  }
182	
183	  static async sign(decisionId: string): Promise<PresenceProof> {
184	    console.warn('[WebAuthn] ⚠️  Using SOFTWARE FALLBACK — not a real presence proof.');
185	    const keys = await this.getOrCreateKey();
186	    const payload = new TextEncoder().encode(
187	      canonicalStringify({
188	        challenge: decisionId,
189	        timestamp: Date.now(),
190	        origin: typeof location !== 'undefined' ? location.origin : 'AskMI-wallet',
191	      })
192	    );
193	    const sig = await crypto.subtle.sign(
194	      { name: 'ECDSA', hash: 'SHA-256' },
195	      keys.privateKey,
196	      payload
197	    );
198	    return {
199	      signature: bufferToBase64(sig),
200	      credentialId: 'software-fallback',
201	      challenge: decisionId,
202	      authenticatorData: '',
203	      verifiedAt: new Date().toISOString(),
204	      method: 'software-fallback',
205	    };
206	  }
207	}
208	
209	// ── WebAuthnService ──────────────────────────────────────────────────────────
210	
211	export class WebAuthnService {
212	  /**
213	   * Registriert den primären Identity-Key für das Wallet.
214	   * Dieser Key ist hardware-gebunden und dient als Root-of-Trust.
215	   */
216	  static async registerIdentityKey(
217	    rpId: string = typeof location !== 'undefined' ? location.hostname : 'localhost'
218	  ): Promise<PasskeyRegistration> {
219	    if (!isWebAuthnAvailable()) {
220	      return this.registerPasskey('AskMI-identity-key', rpId);
221	    }
222	
223	    const userId = 'AskMI-identity-key-v1';
224	    const userIdBuffer = new TextEncoder().encode(userId).buffer;
225	
226	    const createOptions: PublicKeyCredentialCreationOptions = {
227	      rp: { name: 'AskMI Identity', id: rpId },
228	      user: { id: userIdBuffer, name: userId, displayName: 'AskMI Identity Key' },
229	      pubKeyCredParams: [
230	        { type: 'public-key', alg: -7 }, // ES256
231	        { type: 'public-key', alg: -257 }, // RS256 fallback
232	      ],
233	      authenticatorSelection: {
234	        authenticatorAttachment: 'platform',
235	        userVerification: 'required',
236	        residentKey: 'required',
237	      },
238	      attestation: 'none',
239	      challenge: crypto.getRandomValues(new Uint8Array(32)).buffer,
240	    };
241	
242	    const credential = (await navigator.credentials.create({
243	      publicKey: createOptions,
244	    })) as PublicKeyCredential;
245	    const credentialId = bufferToBase64url(credential.rawId);
246	
247	    // Versuche den Public Key zu extrahieren (SPKI)
248	    let publicKeyJwk: JsonWebKey | null = null;
249	    const response = credential.response as AuthenticatorAttestationResponse;
250	    if (typeof response.getPublicKey === 'function') {
251	      const spki = response.getPublicKey();
252	      if (spki) {
253	        // In einer echten Implementierung würden wir SPKI zu JWK konvertieren.
254	        // Für diesen PoC speichern wir die Information dass ein HW-Key existiert.
255	        publicKeyJwk = { kty: 'EC', crv: 'P-256', x: '', y: '', alg: 'ES256', ext: true };
256	      }
257	    }
258	
259	    const registration: PasskeyRegistration = {
260	      credentialId,
261	      publicKeyJwk,
262	      rpId,
263	      registeredAt: new Date().toISOString(),
264	    };
265	
266	    await saveIdentityKeyMeta(registration);
267	    return registration;
268	  }
269	
270	  /**
271	   * Signiert Daten mit dem hardware-gebundenen Identity-Key.
272	   */
273	  static async signWithIdentityKey(data: string): Promise<string> {
274	    const meta = await loadIdentityKeyMeta();
275	    if (!meta || meta.credentialId === 'software-fallback') {
276	      // Fail-closed: a software signature must NEVER stand in for the
277	      // hardware-bound identity key when WebAuthn is available. Only Node/test/
278	      // legacy environments (no navigator.credentials) may use the fallback.
279	      if (isWebAuthnAvailable()) {
280	        throw new Error(
281	          'IDENTITY_KEY_NOT_REGISTERED: refusing software fallback while WebAuthn is available — register the hardware identity key first.'
282	        );
283	      }
284	      const proof = await SoftwareFallback.sign(data);
285	      return proof.signature;
286	    }
287	
288	    // Wir nutzen die Daten als Challenge für eine Assertion
289	    // WebAuthn Challenges sind limitiert (meist 32-64 bytes),
290	    // daher hashen wir die Daten wenn sie zu lang sind.
291	    const dataBuffer = new TextEncoder().encode(data);
292	    const challenge =
293	      dataBuffer.length > 64 ? await crypto.subtle.digest('SHA-256', dataBuffer) : dataBuffer;
294	
295	    const getOptions: PublicKeyCredentialRequestOptions = {
296	      rpId: meta.rpId,
297	      challenge,
298	      allowCredentials: [{ type: 'public-key', id: base64urlToBuffer(meta.credentialId) }],
299	      userVerification: 'required',
300	    };
301	
302	    const assertion = (await navigator.credentials.get({
303	      publicKey: getOptions,
304	    })) as PublicKeyCredential;
305	    const response = assertion.response as AuthenticatorAssertionResponse;
306	
307	    return bufferToBase64(response.signature);
308	  }
309	
310	  /**
311	   * Prüft ob der Identity-Key registriert ist.
312	   */
313	  static async isIdentityRegistered(): Promise<boolean> {
314	    const meta = await loadIdentityKeyMeta();
315	    return meta !== null && meta.credentialId !== 'software-fallback';
316	  }
317	
318	  /**
319	   * Registriert einen Passkey für dieses Gerät.
320	   * Wird beim ersten Wallet-Start aufgerufen (einmalig pro Gerät).
321	   *
322	   * rpId: Muss zum Hostname passen.
323	   *   - localhost → 'localhost'
324	   *   - AskMI.app → 'AskMI.app'
325	   */
326	  static async registerPasskey(
327	    userId: string = 'AskMI-wallet-user',
328	    rpId: string = typeof location !== 'undefined' ? location.hostname : 'localhost'
329	  ): Promise<PasskeyRegistration> {
330	    if (!isWebAuthnAvailable()) {
331	      console.warn('[WebAuthn] navigator.credentials not available. Skipping registration.');
332	      return {
333	        credentialId: 'software-fallback',
334	        publicKeyJwk: null,
335	        rpId,
336	        registeredAt: new Date().toISOString(),
337	      };
338	    }
339	
340	    const userIdBuffer = new TextEncoder().encode(userId).buffer;
341	
342	    const createOptions: PublicKeyCredentialCreationOptions = {
343	      rp: {
344	        name: 'AskMI Personal Trust Hub',
345	        id: rpId,
346	      },
347	      user: {
348	        id: userIdBuffer,
349	        name: userId,
350	        displayName: 'AskMI Wallet',
351	      },
352	      // Wir bevorzugen ES256 (ECDSA P-256), Fallback RS256
353	      pubKeyCredParams: [
354	        { type: 'public-key', alg: -7 }, // ES256
355	        { type: 'public-key', alg: -257 }, // RS256
356	      ],
357	      // Nur Plattform-Authenticator (Fingerprint, FaceID, Windows Hello)
358	      // → kein USB-Key erforderlich
359	      authenticatorSelection: {
360	        authenticatorAttachment: 'platform',
361	        userVerification: 'required', // Biometrie erzwingen
362	        residentKey: 'required', // Passkey (discoverable credential)
363	      },
364	      attestation: 'none', // Kein Server-Attestation (privacy-preserving)
365	      timeout: 60_000,
366	      challenge: crypto.getRandomValues(new Uint8Array(32)).buffer,
367	    };
368	
369	    let credential: PublicKeyCredential;
370	    try {
371	      credential = (await navigator.credentials.create({
372	        publicKey: createOptions,
373	      })) as PublicKeyCredential;
374	    } catch (err) {
375	      if ((err as Error).name === 'NotAllowedError') {
376	        throw new Error('WEBAUTHN_CANCELLED: User cancelled passkey registration.');
377	      }
378	      throw new Error(`WEBAUTHN_REGISTRATION_FAILED: ${(err as Error).message}`);
379	    }
380	
381	    const credentialId = bufferToBase64url(credential.rawId);
382	
383	    const registration: PasskeyRegistration = {
384	      credentialId,
385	      publicKeyJwk: null, // Browser gibt Public Key nicht direkt raus (privacy)
386	      rpId,
387	      registeredAt: new Date().toISOString(),
388	    };
389	
390	    await savePasskeyMeta(registration);
391	    console.log(`[WebAuthn] ✅ Passkey registered: ${credentialId.substring(0, 16)}...`);
392	
393	    return registration;
394	  }
395	
396	  /**
397	   * Führt eine WebAuthn-Assertion durch.
398	   * Die decisionId wird als Challenge verwendet → bindet Biometrie
399	   * kryptographisch an genau diese Policy-Entscheidung.
400	   *
401	   * @param decisionId - UUID aus dem DecisionCapsule
402	   * @returns PresenceProof mit Signatur und Metadaten
403	   */
404	  static async provePresence(decisionId: string): Promise<string> {
405	    const proof = await this.provePresenceDetailed(decisionId);
406	    // Backward-compatible: gibt base64-string zurück wie bisher
407	    return proof.signature;
408	  }
409	
410	  /**
411	   * Wie provePresence(), gibt aber das vollständige PresenceProof-Objekt zurück.
412	   * Verwende diese Variante wenn du authenticatorData etc. brauchst.
413	   */
414	  static async provePresenceDetailed(
415	    decisionId: string,
416	    timeoutMinutes: number = 0
417	  ): Promise<PresenceProof> {
418	    if (!isWebAuthnAvailable()) {
419	      return SoftwareFallback.sign(decisionId);
420	    }
421	
422	    // Check Cache if timeout is configured
423	    if (timeoutMinutes > 0) {
424	      const cachedSessionRaw = sessionStorage.getItem(ASKMI_STORAGE_KEYS.webauthnSession);
425	      if (cachedSessionRaw) {
426	        try {
427	          const cachedSession = JSON.parse(cachedSessionRaw);
428	          const ageMinutes = (Date.now() - cachedSession.timestamp) / (1000 * 60);
429	          if (ageMinutes <= timeoutMinutes) {
430	            console.log(
431	              `[WebAuthn] ⚡ Using cached biometric session (age: ${ageMinutes.toFixed(1)}m / ${timeoutMinutes}m limit)`
432	            );
433	            return {
434	              signature: cachedSession.signature,
435	              credentialId: cachedSession.credentialId,
436	              challenge: decisionId, // Update challenge to match current request context
437	              authenticatorData: cachedSession.authenticatorData,
438	              verifiedAt: cachedSession.verifiedAt,
439	              method: 'webauthn',
440	            };
441	          } else {
442	            console.log(
443	              `[WebAuthn] 🕰️ Cached session expired (${ageMinutes.toFixed(1)}m > ${timeoutMinutes}m). Asking again.`
444	            );
445	            sessionStorage.removeItem(ASKMI_STORAGE_KEYS.webauthnSession);
446	          }
447	        } catch (_e) {
448	          // invalid cache
449	          sessionStorage.removeItem(ASKMI_STORAGE_KEYS.webauthnSession);
450	        }
451	      }
452	    }
453	
454	    // Challenge = decisionId → bindet Biometrie direkt an die Policy (T-24)
455	    // Wir hashen die Challenge nicht mehr, damit der Verifier das Binding prüfen kann
456	    const challengeBytes = new TextEncoder().encode(decisionId);
457	
458	    const rpId = location.hostname;
459	    const existingPasskey = await loadPasskeyMeta();
460	
461	    const allowCredentials: PublicKeyCredentialDescriptor[] =
462	      existingPasskey && existingPasskey.credentialId !== 'software-fallback'
463	        ? [
464	            {
465	              type: 'public-key',
466	              id: base64urlToBuffer(existingPasskey.credentialId),
467	            },
468	          ]
469	        : []; // Leer = Browser zeigt alle verfügbaren Passkeys
470	
471	    const getOptions: PublicKeyCredentialRequestOptions = {
472	      rpId,
473	      challenge: challengeBytes,
474	      allowCredentials,
475	      userVerification: 'required', // Biometrie/PIN erzwingen
476	      timeout: 60_000,
477	    };
478	
479	    let assertion: PublicKeyCredential;
480	    try {
481	      assertion = (await navigator.credentials.get({
482	        publicKey: getOptions,
483	      })) as PublicKeyCredential;
484	    } catch (err) {
485	      const errName = (err as Error).name;
486	
487	      if (errName === 'NotAllowedError') {
488	        throw new Error('WEBAUTHN_CANCELLED: User cancelled biometric verification.');
489	      }
490	      if (errName === 'SecurityError') {
491	        throw new Error('WEBAUTHN_SECURITY_ERROR: rpId mismatch or insecure context.');
492	      }
493	      if (errName === 'InvalidStateError' || errName === 'NotSupportedError') {
494	        // Falls der registrierte Passkey hier nicht greift (z.b. Cross-Device Versuch
495	        // von einem iPad, das den lokalen IndexedDB Passkey vom iPhone nicht hat),
496	        // probieren wir es nochmal OHNE Einschränkung (allowCredentials: []),
497	        // damit das OS den QR-Code Dialog für Cross-Device Auth anbietet.
498	        console.warn(
499	          '[WebAuthn] Local passkey failed or not supported. Falling back to cross-device (QR) flow...'
500	        );
501	        try {
502	          return await this.provePresenceCrossDeviceFallback(decisionId, rpId, challengeBytes);
503	        } catch (fallbackErr) {
504	          console.error('[WebAuthn] Cross-device fallback also failed:', fallbackErr);
505	          throw new Error(
506	            'WEBAUTHN_CROSS_DEVICE_FAILED: Could not authenticate via cross-device flow.'
507	          );
508	        }
509	      }
510	
511	      // Fail-closed: when WebAuthn is available, an assertion failure must NOT
512	      // silently degrade to a software signature — an induced error would
513	      // otherwise bypass the hardware-bound key. Surface the error instead.
